package com.jobhub.resume.application;
import com.jobhub.common.error.*; import com.jobhub.common.id.IdGenerator; import com.jobhub.common.time.UtcTime; import com.jobhub.common.version.VersionCheck; import com.jobhub.resume.domain.*; import com.jobhub.resume.infrastructure.ResumeVersionMapper; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class ResumeVersionService {private final ResumeVersionMapper mapper;private final IdGenerator ids;private final UtcTime time;public ResumeVersionService(ResumeVersionMapper m,IdGenerator i,UtcTime t){mapper=m;ids=i;time=t;}
 @Transactional(readOnly=true) public List<ResumeVersion> list(){return mapper.selectAll();}
 @Transactional public ResumeVersion create(String name,String content){if(name==null||name.isBlank()||content==null||content.isBlank())throw new BusinessRuleException("简历版本名称和内容不能为空");if(name.trim().length()>100||content.length()>30000)throw new BusinessRuleException("简历版本内容超出长度限制");String now=time.now();ResumeVersion v=new ResumeVersion(ids.newId(),name.trim(),content.trim(),now,now,0);mapper.insert(v);return v;}
 @Transactional(readOnly=true) public ResumeVersionComparison compare(String leftId,String rightId){ResumeVersion left=require(leftId),right=require(rightId);if(left.id().equals(right.id()))throw new BusinessRuleException("请选择两个不同的简历版本");Set<String> leftLines=lines(left.content()),rightLines=lines(right.content());List<ResumeVersionComparison.Line> result=new ArrayList<>();for(String line:leftLines)result.add(new ResumeVersionComparison.Line(rightLines.contains(line)?"UNCHANGED":"REMOVED",line));for(String line:rightLines)if(!leftLines.contains(line))result.add(new ResumeVersionComparison.Line("ADDED",line));return new ResumeVersionComparison(left,right,result);}
 private ResumeVersion require(String id){ResumeVersion v=mapper.selectById(id);VersionCheck.requireFound(v,"ResumeVersion",id);return v;} private Set<String> lines(String content){LinkedHashSet<String> r=new LinkedHashSet<>();for(String line:content.split("\\R")){String s=line.trim();if(!s.isEmpty())r.add(s);}return r;}
}
